import cv2
import numpy as np

img = cv2.imread('/work/observations/obs_0001.png')
brown = (img[:, :, 2] > 70) & (img[:, :, 0] < 40) & (img[:, :, 1] < 70)
for col in [172, 175, 185, 238, 240]:
    rows = np.where(brown[:, col])[0]
    if len(rows) > 0:
        print(f'col {col}: rows {np.min(rows)} to {np.max(rows)}')

# Let's find all vertical legs of this table
for col in range(165, 250):
    rows = np.where(brown[:, col])[0]
    if len(rows) > 0 and np.max(rows) > 310:
        print(f'col {col}: max row {np.max(rows)}')
